import json
from pathlib import Path

import matplotlib

matplotlib.use('Agg')
import matplotlib.pyplot as plt

r=json.loads(Path('reports/evaluation.json').read_text())
fig,axs=plt.subplots(1,3,figsize=(15,4))
for m,c in r['curves'].items():
    axs[0].plot(c['roc']['fpr'],c['roc']['tpr'],label=m)
    axs[1].plot(c['pr']['recall'],c['pr']['precision'],label=m)
    axs[2].plot(c['calibration']['predicted'],c['calibration']['observed'],marker='o',label=m)
axs[0].plot([0,1],[0,1],'k--');axs[0].set(xlabel='False positive rate',ylabel='True positive rate',title='Frozen final test: ROC')
axs[1].set(xlabel='Recall',ylabel='Precision',title='Precision–recall')
axs[2].plot([0,1],[0,1],'k--');axs[2].set(xlabel='Predicted risk',ylabel='Observed missed fraction',title='Quantile calibration')
for ax in axs:ax.grid(alpha=.2)
axs[0].legend(fontsize=6);fig.tight_layout();fig.savefig('reports/evaluation-curves.png',dpi=150);plt.close(fig)
lines=['# CareAccess ML: frozen evaluation report','','## Key finding','The software performs real trained-model inference, but discrimination is approximately chance. Useful operational prioritization is NOT established. Do not deploy for clinical operations without local validation and prospective governance.','','## Source and sample',f"Original {r['counts']['original_rows']:,} records; {r['counts']['exact_duplicate_rows_removed']:,} exact duplicate rows removed; {r['counts']['clean_rows']:,} retained. 8,905 held-out appointments from 2021–2022, including 1,433 missed visits (16.09%).",'','## Models (final test)','|Model|ROC-AUC|Average precision|Brier|Precision|Recall|F1|Threshold|','|---|---:|---:|---:|---:|---:|---:|---:|']
for m in r['metrics']:lines.append('|'+m['model']+'|'+ '|'.join(f"{m[k]:.4f}" for k in ['roc_auc','average_precision','brier','precision','recall','f1','threshold'])+'|')
lines+=['','Average precision baseline on the test set is its missed-visit prevalence. Accuracy is deliberately not promoted. Thresholds maximize F1 on calibration data; their very high recall and poor specificity do not justify contacting everyone. Capacity selection is separately reported per day.','','## Selection and calibration',r['selection']['rule'],'All candidate hyperparameters fixed before training. PyTorch uses actual AdamW weight updates, two hidden layers (32/16), validation loss early stopping. Train-only imputation/scaling/encoding. Calibration is sigmoid fit on 2020, threshold grid 0.05–0.95 also on 2020. HistGB sigmoid slope is negative in this temporal sample: discrimination was weak/reversed during calibration, further evidence of instability; no test-driven correction was made.','','## Audit ordering',r['audit_order'],'','## Additional-input necessity','Development-only HistGB ablations considered disability and city. Each reduced 2019 validation AP and worsened Brier; the minimal predictors were retained. This does not prove such features are universally useless. ICD was excluded because preappointment recording time was not established and historical missingness is severe.','','## Uncertainty','95% percentile intervals use 200 date-cluster bootstrap replicates of fixed final-test predictions; they are conditional on the fitted models and cannot account fully for repeated patients. Full intervals, subgroup counts, daily Precision@K/Recall@K, curves and matrices are in evaluation.json. Small groups (<100 records or <20 events/non-events) suppressed.','','## Limitations']+['- '+v for v in r['limitations']]+['','## Reproducibility','See docs/retraining.md, models/manifest.json, reports/source-audit.json and reports/feature_ablation.json. No row-level original/cleaned data or held-out patient predictions are included.']
Path('reports/evaluation-report.md').write_text('\n'.join(lines)+'\n')
for m in r['metrics']:
    slug={'Constant baseline':'baseline','Logistic Regression':'logistic','Gradient Boosting':'gradient','PyTorch Neural Network':'neural'}[m['model']]
    text=f"# Model card: {m['model']}\n\nVersion 0.1.0. Trained {r['created_utc']}. Source Mendeley DOI10.17632/wm6w2fvkfj.1, CC BY4.0.\n\n## Intended use\nReproducible retrospective evaluation and authorized nonidentifying input inference of supportive appointment outreach. Not validated for operational deployment. Never use for eligibility, cancellation, punishment, or reduced access to care.\n\n## Training\n29,187 appointments before2019; 7,753 validation2019; 827 calibration2020; 8,905 finaltest2021–2022. Predictors: specialty, age at appointment, scheduled hour, weekday and month. No outcome reasons, observed weather, DOB, diagnoses or direct identifiers enter inference.\n\n## Evaluation\nROC-AUC {m['roc_auc']:.4f}; AP {m['average_precision']:.4f}; Brier {m['brier']:.4f}. Near-chance discrimination; no proven beneficial prioritization. Full metrics/confidence intervals/subgroups and limitations in evaluation.json.\n\n## Safe artifacts\nBundled sklearn objects loaded with skops type checks; neural weights use safetensors. SHA256 checksums in manifest. No user-uploaded models. Models may encode historical associations and are not guaranteed privacy-preserving.\n\n## Limitations\nNo reliable patient identifier, possible repeated-person overlap, temporal/pandemic shift, modest/sparse calibration sample, single rehabilitation service, no causal outreach evaluation. Missing age imputed from training only. Unknown specialties rejected; blanks explicitly missing.\n"
    Path(f'docs/model-card-{slug}.md').write_text(text)
